const d = $input.first().json ?? {};

const texto = (v) => String(v ?? '').trim();
const primero = (...valores) => valores.find(v => texto(v) !== '');

function fechaParaBanxico(valor) {
  const s = texto(valor);
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[3] + '-' + m[2] + '-' + m[1];
  m = s.match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})/);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  return '';
}

function numero(valor) {
  if (typeof valor === 'number') return Number.isFinite(valor) ? valor : null;
  const limpio = texto(valor)
    .replace(/MXN/gi, '')
    .replace(/\$/g, '')
    .replace(/,/g, '')
    .replace(/\s/g, '');
  if (!limpio) return null;
  const n = Number(limpio);
  return Number.isFinite(n) ? n : null;
}

const fechaPago = fechaParaBanxico(primero(
  d.fecha_pago,
  d.fecha,
  d.transferencia?.fecha,
  d.ocr?.fecha_pago,
));

const claveRastreo = texto(primero(
  d.clave_rastreo,
  d.claveRastreo,
  d.rastreo,
  d.transferencia?.clave_rastreo,
  d.ocr?.clave_rastreo,
));

const referencia = texto(primero(
  d.numero_referencia,
  d.referencia,
  d.transferencia?.referencia,
  d.ocr?.referencia,
));

const tipoCriterio = claveRastreo ? 'T' : 'R';
const criterioBusqueda = claveRastreo || referencia;

const bancoEmisor = texto(primero(
  d.banco_emisor,
  d.institucion_emisora,
  d.transferencia?.banco_emisor,
  d.ocr?.banco_emisor,
));

const bancoReceptor = texto(primero(
  d.banco_receptor,
  d.institucion_receptora,
  d.transferencia?.banco_receptor,
  d.ocr?.banco_receptor,
  'BBVA MEXICO',
));

const cuentaBeneficiaria = texto(primero(
  d.cuenta_beneficiaria,
  d.clabe_beneficiaria,
  d.transferencia?.cuenta_beneficiaria,
  d.ocr?.cuenta_beneficiaria,
)).replace(/\D/g, '');

const cuentaDestinoEsperada = texto(primero(
  d.cuenta_destino_esperada,
  '012225004875095530',
)).replace(/\D/g, '');

const montoPago = numero(primero(
  d.monto_pago,
  d.monto,
  d.transferencia?.monto,
  d.ocr?.monto,
));

const personas = numero(primero(d.numero_personas, d.personas));
const montoEsperado = numero(primero(
  d.monto_esperado,
  d.deposito_esperado,
  personas ? personas * 500 : null,
));

const subscriberId = texto(primero(
  d.subscriber_id,
  d.subscriberId,
  d.suscriber_id,
  d.body?.id,
  d.body?.subscriber_id,
));

const liveChatUrl = texto(primero(
  d.live_chat_url,
  d.body?.live_chat_url,
  subscriberId ? 'https://app.manychat.com/fb1346079/chat/' + encodeURIComponent(subscriberId) : '',
));

const faltantes = [];
if (!fechaPago) faltantes.push('fecha_pago');
if (!criterioBusqueda || /^CAMBIAR/i.test(criterioBusqueda)) faltantes.push('clave_rastreo o numero_referencia');
if (!bancoEmisor || /^CAMBIAR/i.test(bancoEmisor)) faltantes.push('banco_emisor');
if (!bancoReceptor) faltantes.push('banco_receptor');
if (!cuentaBeneficiaria) faltantes.push('cuenta_beneficiaria');
if (!(montoPago > 0)) faltantes.push('monto_pago');
if (!(montoEsperado > 0)) faltantes.push('monto_esperado o numero_personas');

const cuentaCoincide = Boolean(
  cuentaBeneficiaria &&
  cuentaDestinoEsperada &&
  cuentaBeneficiaria === cuentaDestinoEsperada
);

const montoCoincide = Boolean(
  montoPago !== null &&
  montoEsperado !== null &&
  Math.abs(montoPago - montoEsperado) < 0.01
);

return [{
  json: {
    ...d,
    fecha_banxico: fechaPago,
    tipo_criterio: tipoCriterio,
    criterio_busqueda: criterioBusqueda,
    banco_emisor: bancoEmisor,
    banco_receptor: bancoReceptor,
    cuenta_beneficiaria: cuentaBeneficiaria,
    cuenta_destino_esperada: cuentaDestinoEsperada,
    monto_pago: montoPago,
    monto_esperado: montoEsperado,
    cuenta_coincide: cuentaCoincide,
    monto_coincide: montoCoincide,
    subscriber_id: subscriberId,
    live_chat_url: liveChatUrl,
    datos_completos: faltantes.length === 0,
    faltantes,
  },
}];

const d = $input.first().json;

const token = String(d.browserless_token ?? '').trim();
if (!token || /^CAMBIAR|^PEGA_/i.test(token)) {
  throw new Error('Configura browserless_token en el nodo CONFIGURAR Browserless');
}

return [{
  json: {
    ...d,
    browserless_endpoint: 'http://browserless:3000/function',
    browserless_token: token,
    browserless_payload: {
      code: "export default async ({ page, context }) => {
  const responder = (estado, detalle = '', texto = '', extra = {}) => ({
    data: {
      ok: estado === 'liquidado',
      estado_banxico: estado,
      captcha_requerido: estado === 'requiere_codigo_seguridad',
      texto_resultado: texto,
      error: detalle,
      ...extra,
    },
    type: 'application/json',
  });

  const normalizar = (v) => String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toUpperCase();

  async function asignar(selector, valor) {
    await page.$eval(selector, (el, nuevoValor) => {
      const proto = el.tagName === 'TEXTAREA'
        ? HTMLTextAreaElement.prototype
        : HTMLInputElement.prototype;
      const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
      if (setter) setter.call(el, String(nuevoValor));
      else el.value = String(nuevoValor);
      for (const tipo of ['input', 'change', 'keyup', 'blur']) {
        el.dispatchEvent(new Event(tipo, { bubbles: true }));
      }
    }, valor);
  }

  async function seleccionarBanco(selector, banco) {
    const valor = await page.$eval(selector, (select, buscado) => {
      const norm = (v) => String(v ?? '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .trim()
        .toUpperCase();
      const limpiar = (v) => norm(v).split('(')[0].trim();
      const genericas = new Set(['BANCO','BANCA','DE','DEL','LA','EL','SA','CV','SOFOM','ENR','INSTITUCION','NACIONAL','CREDITO','SERVICIOS','FINANCIEROS','GRUPO','MULTIPLE','MEXICO','Y']);
      const palabras = limpiar(buscado).split(' ').filter(p => p.length > 2 && !genericas.has(p));
      const objetivos = [...new Set([
        norm(buscado),
        limpiar(buscado),
        palabras.join(' '),
        palabras.slice(0, 2).join(' ')
      ].filter(v => v && v.length >= 4))];
      const opciones = Array.from(select.options);
      const porCodigo = opciones.find(o => String(o.value) === String(buscado));
      if (porCodigo) return porCodigo.value;
      for (const objetivo of objetivos) {
        const exacto = opciones.find(o => norm(o.textContent) === objetivo);
        if (exacto) return exacto.value;
      }
      for (const objetivo of objetivos) {
        const contenido = opciones.find(o => norm(o.textContent).includes(objetivo));
        if (contenido) return contenido.value;
      }
      for (const palabra of [...palabras].sort((a, b) => b.length - a.length)) {
        if (palabra.length < 5) continue;
        const porPalabra = opciones.find(o => norm(o.textContent).includes(palabra));
        if (porPalabra) return porPalabra.value;
      }
      return '';
    }, banco);
    if (!valor) throw new Error('Banco no reconocido por Banxico: ' + banco);
    await page.select(selector, valor);
    return valor;
  }

  async function captchaVisible() {
    return await page.$eval('#captchaImage', (el) => {
      const estilo = window.getComputedStyle(el);
      const rect = el.getBoundingClientRect();
      return !el.classList.contains('oculta') &&
        estilo.display !== 'none' &&
        estilo.visibility !== 'hidden' &&
        rect.width > 0 && rect.height > 0;
    }).catch(() => false);
  }

  try {
    await page.goto('https://www.banxico.org.mx/cep/', {
      waitUntil: 'networkidle2',
      timeout: 30000,
    });
    await page.waitForSelector('#input_fecha', { visible: true, timeout: 15000 });

    // Al cambiar la fecha, Banxico vuelve a cargar por AJAX los dos selectores
    // de instituciones. Hay que esperar esa respuesta antes de seleccionar
    // bancos; de lo contrario la respuesta AJAX borra las selecciones.
    const fechaCodificada = encodeURIComponent(context.fecha_banxico);
    const institucionesCargadas = page.waitForResponse(
      response =>
        response.url().includes('/cep/instituciones.do?fecha=' + fechaCodificada) &&
        response.status() === 200,
      { timeout: 15000 },
    ).catch(() => null);

    await asignar('#input_fecha', context.fecha_banxico);
    const respuestaInstituciones = await institucionesCargadas;

    if (!respuestaInstituciones) {
      return responder(
        'instituciones_no_cargadas',
        'Banxico no terminó de cargar las instituciones para la fecha solicitada.',
      );
    }

    await page.waitForFunction(() => {
      const emisor = document.querySelector('#input_emisor');
      const receptor = document.querySelector('#input_receptor');
      return emisor?.options?.length > 1 && receptor?.options?.length > 1;
    }, { timeout: 8000 });

    // El código de Banxico espera 500 ms después del AJAX y vuelve a elegir
    // un receptor predeterminado. Esperamos ese temporizador para que no borre
    // la selección que se hará a continuación.
    await new Promise(resolve => setTimeout(resolve, 800));

    await page.select('#input_tipoCriterio', context.tipo_criterio);
    await asignar('#input_criterio', context.criterio_busqueda);
    await seleccionarBanco('#input_emisor', context.banco_emisor);
    await seleccionarBanco('#input_receptor', context.banco_receptor);
    await asignar('#input_cuenta', context.cuenta_beneficiaria);
    await asignar('#input_monto', Number(context.monto_pago).toFixed(2));

    if (await captchaVisible()) {
      return responder(
        'requiere_codigo_seguridad',
        'Banxico mostró la imagen de seguridad; se requiere revisión humana.',
      );
    }

    // El botón depende de un manejador jQuery que no siempre se ejecuta dentro
    // de Browserless. Enviamos, desde la misma página y con la misma sesión, el
    // POST que realiza el JavaScript oficial de Banxico a valida.do.
    const resultadoConsulta = await page.evaluate(async () => {
      const campo = (nombre) => document.querySelector('[name="' + nombre + '"]');
      const valor = (nombre) => String(campo(nombre)?.value ?? '').trim();
      const campoCaptcha = campo('captcha');

      const payload = {
        tipoCriterio: valor('tipoCriterio'),
        fecha: valor('fecha'),
        criterio: valor('criterio'),
        emisor: valor('emisor'),
        receptor: valor('receptor'),
        cuenta: valor('cuenta'),
        receptorParticipante: valor('receptorParticipante') || '0',
        monto: valor('monto').replace(/[, ]/g, ''),
        captcha: campoCaptcha ? String(campoCaptcha.value ?? '').trim() : 'c',
        tipoConsulta: '0',
      };

      const obligatorios = [
        'tipoCriterio',
        'fecha',
        'criterio',
        'emisor',
        'receptor',
        'cuenta',
        'monto',
      ];
      const faltantes = obligatorios.filter(nombre => !payload[nombre]);
      if (faltantes.length) {
        return {
          okHttp: false,
          status: 0,
          contentType: '',
          texto: '',
          error: 'Campos vacíos antes de consultar: ' + faltantes.join(', '),
        };
      }

      const controller = new AbortController();
      const temporizador = setTimeout(() => controller.abort(), 120000);

      try {
        const respuesta = await fetch('valida.do', {
          method: 'POST',
          credentials: 'same-origin',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            'X-Requested-With': 'XMLHttpRequest',
          },
          body: new URLSearchParams(payload).toString(),
          signal: controller.signal,
        });

        const html = await respuesta.text();
        const documento = new DOMParser().parseFromString(String(html ?? ''), 'text/html');
        documento.querySelectorAll('script, style, noscript, template').forEach(el => el.remove());
        const contenedor = documento.querySelector('#consultaMISPEI') || documento.body;
        let texto = String(contenedor?.innerText || contenedor?.textContent || '')
          .replace(/\u00a0/g, ' ')
          .replace(/[ \t]+/g, ' ')
          .replace(/\n\s*\n+/g, '\n')
          .trim();

        // La respuesta también contiene un glosario con todos los estados.
        // Se elimina para que "Liquidado" no provoque falsos positivos cuando
        // el estado real sea No encontrado, Devuelto, Rechazado, etc.
        const inicioGlosario = texto.search(/Descripción de los estados del pago/i);
        if (inicioGlosario >= 0) texto = texto.slice(0, inicioGlosario).trim();

        return {
          okHttp: respuesta.ok,
          status: respuesta.status,
          contentType: respuesta.headers.get('content-type') || '',
          texto,
          error: respuesta.ok ? '' : 'Banxico respondió HTTP ' + respuesta.status,
        };
      } catch (error) {
        return {
          okHttp: false,
          status: 0,
          contentType: '',
          texto: '',
          error: error?.name === 'AbortError'
            ? 'La consulta directa a Banxico excedió 120 segundos.'
            : String(error?.message ?? error),
        };
      } finally {
        clearTimeout(temporizador);
      }
    });

    if (!resultadoConsulta.okHttp && !resultadoConsulta.texto) {
      return responder(
        'error_consulta_banxico',
        resultadoConsulta.error || 'Banxico no devolvió contenido para interpretar.',
        '',
        {
          formulario_enviado: true,
          http_status_banxico: resultadoConsulta.status,
          content_type_banxico: resultadoConsulta.contentType,
        },
      );
    }

    const textoResultado = resultadoConsulta.texto;

    const plano = normalizar(textoResultado);
    const coincidenciaEstado = plano.match(
      /ESTADO DEL PAGO EN BANXICO\s*(EN PROCESO DE DEVOLUCION|NO LIQUIDADO|NO ENCONTRADO|EN PROCESO|LIQUIDADO|DEVUELTO|CANCELADO|RECHAZADO|RETORNADO)/,
    );
    const estados = {
      'LIQUIDADO': 'liquidado',
      'EN PROCESO': 'pendiente',
      'EN PROCESO DE DEVOLUCION': 'en_proceso_de_devolucion',
      'DEVUELTO': 'devuelto',
      'CANCELADO': 'cancelado',
      'RECHAZADO': 'rechazado',
      'NO LIQUIDADO': 'no_liquidado',
      'NO ENCONTRADO': 'no_encontrado',
      'RETORNADO': 'retornado',
    };
    const estado = estados[coincidenciaEstado?.[1]] || 'respuesta_no_reconocida';

    return responder(
      estado,
      estado === 'respuesta_no_reconocida'
        ? 'Banxico respondió, pero el estado no pudo interpretarse.'
        : '',
      textoResultado.slice(0, 20000),
      {
        formulario_enviado: true,
        http_status_banxico: resultadoConsulta.status,
        content_type_banxico: resultadoConsulta.contentType,
      },
    );
  } catch (error) {
    return responder(
      'error_automatizacion',
      String(error?.message ?? error),
    );
  }
};",
      context: {
        fecha_banxico: d.fecha_banxico,
        tipo_criterio: d.tipo_criterio,
        criterio_busqueda: d.criterio_busqueda,
        banco_emisor: d.banco_emisor,
        banco_receptor: d.banco_receptor,
        cuenta_beneficiaria: d.cuenta_beneficiaria,
        monto_pago: d.monto_pago,
      },
    },
  },
}];

const respuesta = $input.first().json ?? {};
const original = $('Preparar consulta Browserless').first().json;

let resultado = respuesta;
if (resultado.data && typeof resultado.data === 'object') resultado = resultado.data;
if (resultado.data && typeof resultado.data === 'object') resultado = resultado.data;

const textoResultado = String(
  resultado.texto_resultado ??
  resultado.text ??
  resultado.content ??
  ''
).trim();

const normalizar = (v) => String(v ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .toUpperCase();

const plano = normalizar(textoResultado);
const compacto = plano.replace(/[^A-Z0-9]/g, '');
const soloDigitos = textoResultado.replace(/\D/g, '');
const cuenta = String(original.cuenta_destino_esperada ?? '');

const estadoMatch = plano.match(
  /ESTADO DEL PAGO EN BANXICO\s*:?\s*(EN PROCESO DE DEVOLUCION|NO LIQUIDADO|NO ENCONTRADO|EN PROCESO|LIQUIDADO|DEVUELTO|CANCELADO|RECHAZADO|RETORNADO)/,
);
const estadosBanxico = {
  'LIQUIDADO': 'liquidado',
  'EN PROCESO': 'pendiente',
  'EN PROCESO DE DEVOLUCION': 'en_proceso_de_devolucion',
  'DEVUELTO': 'devuelto',
  'CANCELADO': 'cancelado',
  'RECHAZADO': 'rechazado',
  'NO LIQUIDADO': 'no_liquidado',
  'NO ENCONTRADO': 'no_encontrado',
  'RETORNADO': 'retornado',
};
const estadoBanxico = estadosBanxico[estadoMatch?.[1]] || 'respuesta_no_reconocida';

const montoMatch = textoResultado.match(
  /(?:^|\n)\s*Monto\s*:?\s*\$?\s*([\d,]+(?:\.\d{1,2})?)/im,
);
const montoPdf = montoMatch
  ? Number(String(montoMatch[1]).replace(/,/g, ''))
  : null;
const montoEsperado = Number(original.monto_esperado);

const criterio = normalizar(original.criterio_busqueda).replace(/[^A-Z0-9]/g, '');
const bancoEmisor = normalizar(original.banco_emisor);
const bancoReceptor = normalizar(original.banco_receptor);
const fechaEsperada = String(original.fecha_banxico ?? '').replace(/-/g, '/');

const paginaConfirmaCuenta = Boolean(cuenta && soloDigitos.includes(cuenta));
const paginaConfirmaMonto = Boolean(
  Number.isFinite(montoPdf) &&
  Number.isFinite(montoEsperado) &&
  Math.abs(montoPdf - montoEsperado) < 0.01
);
const paginaConfirmaCriterio = Boolean(criterio && compacto.includes(criterio));
const paginaConfirmaFecha = Boolean(fechaEsperada && textoResultado.includes(fechaEsperada));
const paginaConfirmaBancoEmisor = Boolean(bancoEmisor && plano.includes(bancoEmisor));
const paginaConfirmaBancoReceptor = Boolean(bancoReceptor && plano.includes(bancoReceptor));
const liquidado = estadoBanxico === 'liquidado';
const esReporteEstado = /ESTA CONSULTA NO ES UN COMPROBANTE ELECTRONICO DE PAGO/.test(plano);

// Confirmación estricta usando el contenido devuelto por valida.do de Banxico.
const pagoVerificado = Boolean(
  liquidado &&
  original.cuenta_coincide === true &&
  original.monto_coincide === true &&
  paginaConfirmaCuenta &&
  paginaConfirmaMonto &&
  paginaConfirmaCriterio &&
  paginaConfirmaFecha &&
  paginaConfirmaBancoEmisor &&
  paginaConfirmaBancoReceptor
);

const motivos = [];
if (!textoResultado) motivos.push('Banxico no devolvió texto interpretable');
if (!liquidado) motivos.push('estado Banxico: ' + estadoBanxico);
if (!original.cuenta_coincide) motivos.push('la cuenta del comprobante no coincide');
if (!original.monto_coincide) motivos.push('el monto no coincide con el depósito esperado');
if (!paginaConfirmaCuenta) motivos.push('la respuesta no corroboró la cuenta completa');
if (!paginaConfirmaMonto) motivos.push('la respuesta no corroboró el monto');
if (!paginaConfirmaCriterio) motivos.push('la respuesta no corroboró la clave de rastreo o referencia');
if (!paginaConfirmaFecha) motivos.push('la respuesta no corroboró la fecha del pago');
if (!paginaConfirmaBancoEmisor) motivos.push('la respuesta no corroboró el banco emisor');
if (!paginaConfirmaBancoReceptor) motivos.push('la respuesta no corroboró el banco receptor');
if (resultado.error) motivos.push(String(resultado.error));

return [{
  json: {
    ...original,
    ...resultado,
    intentos_validacion: 1,
    estado_banxico: estadoBanxico,
    tipo_documento_banxico: esReporteEstado ? 'reporte_estado_pago' : 'respuesta_banxico',
    texto_resultado: textoResultado.slice(0, 20000),
    monto_detectado_pdf: montoPdf,
    pago_liquidado_banxico: liquidado,
    pagina_confirma_cuenta: paginaConfirmaCuenta,
    pagina_confirma_monto: paginaConfirmaMonto,
    pagina_confirma_criterio: paginaConfirmaCriterio,
    pagina_confirma_fecha: paginaConfirmaFecha,
    pagina_confirma_banco_emisor: paginaConfirmaBancoEmisor,
    pagina_confirma_banco_receptor: paginaConfirmaBancoReceptor,
    pago_verificado: pagoVerificado,
    requiere_asesor: !pagoVerificado,
    motivo_revision: motivos.join(' | ') || null,
  },
}];

const d = $input.first().json ?? {};
const reservaDraftId = String(d.reserva_draft_id ?? d.draft_id ?? '').trim();
const subscriberId = String(d.subscriber_id ?? '').trim();

return [{
  json: {
    ...d,
    reserva_draft_id: reservaDraftId,
    puede_actualizar_supabase:
      /^\d+$/.test(reservaDraftId) && /^\d+$/.test(subscriberId),
  },
}];

const actualizado = $input.first().json ?? {};
const validacion = $('Resultado bancario definitivo').first().json ?? {};
const reservaDraftId = String(validacion.reserva_draft_id ?? '').trim();

const pagoRecibido =
  actualizado.pago_recibido === true ||
  ['true', '1', 'si', 'sí', 'yes'].includes(
    String(actualizado.pago_recibido ?? '').trim().toLowerCase()
  );

const idCoincide =
  reservaDraftId !== '' &&
  String(actualizado.id ?? '').trim() === reservaDraftId;

const supabaseActualizado = Boolean(idCoincide && pagoRecibido);

return [{
  json: {
    ...validacion,
    ...actualizado,
    reserva_draft_id: reservaDraftId,
    supabase_actualizado: supabaseActualizado,
    pago_verificado: validacion.pago_verificado === true && supabaseActualizado,
    requiere_asesor: !supabaseActualizado,
    motivo_revision: supabaseActualizado
      ? null
      : 'Banxico confirmó el pago, pero Supabase no devolvió el borrador actualizado.',
  },
}];

const d = $input.first().json;
return [{
  json: {
    ...d,
    resultado: 'PAGO_VERIFICADO',
    mensaje: 'Banxico confirmó el pago y los datos coinciden con la reserva.',
  },
}];

const d={...$input.first().json};
delete d.browserless_token; delete d.browserless_payload;
const faltantes=Array.isArray(d.faltantes)?d.faltantes:[];
